<?php

/**
 * Prueba Simple de Similitud de Coseno
 * Este script contiene la clase VectorMathUtility con las funciones
 * dotProduct, magnitude y cosineSimilarity, y un bloque de prueba
 * para verificar la similitud entre dos vectores (U y P) específicos.
 */

class VectorMathUtility
{
    /**
     * Calcula la magnitud (norma L2) de un vector.
     * @param array $vector
     * @return float
     */
    public function magnitude(array $vector): float
    {
        $sumOfSquares = 0.0;
        foreach ($vector as $value) {
            $sumOfSquares += $value * $value;
        }
        return sqrt($sumOfSquares);
    }

    /**
     * Calcula el producto punto (dot product) de dos vectores.
     * @param array $vectorA
     * @param array $vectorB
     * @return float
     * @throws Exception Si las dimensiones no coinciden.
     */
    public function dotProduct(array $vectorA, array $vectorB): float
    {
        if (count($vectorA) !== count($vectorB)) {
            throw new Exception("Los vectores deben tener la misma dimensión para el producto punto.");
        }

        $product = 0.0;
        foreach ($vectorA as $index => $value) {
            $product += $value * $vectorB[$index];
        }
        return $product;
    }

    /**
     * Calcula la similitud de coseno entre dos vectores.
     * @param array $vectorA
     * @param array $vectorB
     * @return float El valor de similitud entre -1.0 y 1.0.
     */
    public function cosineSimilarity(array $vectorA, array $vectorB): float
    {
        try {
            $dotProduct = $this->dotProduct($vectorA, $vectorB);
            $magnitudeA = $this->magnitude($vectorA);
            $magnitudeB = $this->magnitude($vectorB);
        } catch (Exception $e) {
            // Si la dimensión no coincide, devolvemos 0
            echo "Error de dimensión: " . $e->getMessage() . "\n";
            return 0.0;
        }

        // Previene la división por cero si uno o ambos vectores tienen magnitud 0.
        if ($magnitudeA == 0.0 || $magnitudeB == 0.0) {
            return 0.0;
        }

        $similarity = $dotProduct / ($magnitudeA * $magnitudeB);

        // Asegura que el valor esté entre -1 y 1 (evita errores de precisión flotante)
        return max(-1.0, min(1.0, $similarity));
    }
}

